8.content:
let fm_rebook = ZT.getVariableValue("fm_rebook", null)
let who_rebook = ZT.getVariableValue("who_rebook", null)
let reb_permitted = ZT.getVariableValue("reb_permitted", null)
let rebooking_reason = ZT.getVariableValue("rebooking_reason", null)
let isSpecialCarrier = ZT.getVariableValue("isSpecialCarrier",undefined)

let outcome = "";
if (fm_rebook == "Refer the customer to airline") {
    outcome = "The customer will need to contact the airline to proceed with the rebooking due to Force Majeure situation."
} else if (who_rebook == "Customer") {
    outcome = "We cannot assist with rebooking due to technical limitations. The customer should contact the airline directly to proceed with the request."
} else if (reb_permitted == "No") {
    outcome = "Rebooking is not permitted. However, the customer may contact the airline directly."
} else if (rebooking_reason == "gdpr") {
    outcome = "We cannot assist with rebooking due to GDPR for this booking. The customer will have to contact the airline directly to process the request."
}

let is_special_carrier_html = isSpecialCarrier?`<p>Is Special Carrier: True</p>`:``;
ZT.setTransformData('is_special_carrier_html', is_special_carrier_html)
ZT.setFormData("outcome", outcome);
ZT.setFormData("new_flights", "N/A");
ZT.setFormData("proceedHandling", "Refer to airline");

